/**
 * Generated by quail.
 *
 * Visual regression baseline for https://www.spritecloud.com/functional-testing. Full-page screenshot per
 * viewport (mobile / tablet / desktop) diffed against committed
 * baselines. First run captures; subsequent runs diff.
 *
 * Update baselines after an intentional UI change:
 *   npm run test:visual-update
 *   # then commit the changed PNGs
 *
 * Filter: `npx playwright test --grep @kind:visual`
 */
import { test, expect } from '@playwright/test'
import { VIEWPORTS } from '../prims'

test.describe.configure({ mode: 'parallel' })
test.describe('Spritecloud — visual regression @ https://www.spritecloud.com/functional-testing', () => {
  for (const vp of VIEWPORTS) {
    test(`@kind:visual @smoke page matches baseline (${vp.name})`, async ({ page }) => {
      await page.setViewportSize({ width: vp.width, height: vp.height })
      await page.goto('https://www.spritecloud.com/functional-testing')
      await page.waitForLoadState('networkidle').catch(() => {})
      await expect(page).toHaveScreenshot(`spritecloud-${vp.name}.png`, {
        fullPage: true,
        maxDiffPixelRatio: 0.01,
        animations: 'disabled',
      })
    })
  }
})
